<?php
require __DIR__.'/_init.php';require_once ROOT.'/app/domain.php';require_once ROOT.'/app/playlist_copy.php';require_once ROOT.'/app/playlist_generator.php';require_permission('playlists.edit');
$error='';$created=[];$tid=company_scope(isset($_GET['tenant_id'])?(string)$_GET['tenant_id']:(isset($_GET['company'])?(string)$_GET['company']:null))??tenant();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$tid=post_tenant();$created=ds_generate_playlists($tid,(array)($_POST['media_ids']??[]),$_POST);}catch(Throwable $e){$error=$e instanceof PDOException?fault($e,'playlist_generator'):$e->getMessage();}}
$media=dball('SELECT * FROM media WHERE (tenant_id=? OR is_shared=1) AND separator_key IS NULL ORDER BY orientation,layout_type,name',[$tid]);
render('Generar listas automáticamente',function()use($media,$tid,$error,$created){
 if($error)echo '<div class="alert alert-danger">'.h($error).'</div>';
 foreach($created as $p)echo '<p class="alert alert-success">Creada: <a href="'.h(url('playlists.php?company='.$tid.'#playlist-'.$p['id'])).'">'.h($p['name']).'</a> · '.$p['items'].' renglones</p>';
 echo '<p>Selecciona medios. Se generará una lista por formato y orientación, con el nombre de la empresa y los modos elegidos. Los archivos se reutilizan.</p><form method="get" class="ds-filters">'.company_select($tid).'<button class="btn btn-outline-primary" name="load" value="1">Cargar empresa</button></form>';
 // GET company selector uses tenant_id; normalize to explicit company route in JS and server below.
 form_open();echo '<input type="hidden" name="tenant_id" value="'.$tid.'">'.ds_playlist_modes_form().'<div class="row g-2 mb-3"><div class="col-md-3"><label>Duración común (s)</label><input name="duration" type="number" min="0.1" max="86400" step="0.1" value="10" required class="form-control"></div><div class="col-md-3"><label>Transición común</label>'.sel('transition_effect',transitions(),'fade').'</div><div class="col-md-3"><label>Duración efecto (ms)</label><input name="transition_ms" type="number" min="0" max="3000" value="600" required class="form-control"></div><div class="col-md-3"><label>Separador después de cada medio</label><select name="separator_color" class="form-select"><option value="">Sin separadores</option><option value="#ffffff">Blanco</option><option value="#000000">Negro</option></select><label>Duración separador (s)</label><input name="separator_duration" type="number" min="0.1" max="86400" step="0.1" value="0.1" class="form-control"></div></div><input type="search" class="form-control mb-2" placeholder="Buscar medio" data-generator-search><label><input type="checkbox" data-generator-all> Seleccionar todos los visibles</label><div class="card table-responsive"><table class="table table-sm"><thead><tr><th></th><th>Miniatura</th><th>Medio</th><th>Formato</th><th>Orientación</th><th>Dimensiones</th></tr></thead><tbody>';
 foreach($media as $m)echo '<tr data-generator-row><td><input type="checkbox" name="media_ids[]" value="'.$m['id'].'"></td><td>'.(str_starts_with($m['mime'],'image/')?'<img loading="lazy" src="'.h(url('media-thumbnail.php?id='.$m['id'])).'" width="80" height="45" style="object-fit:contain" alt="Miniatura">':'<video muted preload="metadata" src="'.h(url('media-file.php?id='.$m['id'])).'" width="80" height="45"></video>').'</td><td>'.h($m['name']).'</td><td>'.h(layouts()[$m['layout_type']]).'</td><td>'.h(orientations()[$m['orientation']]).'</td><td>'.$m['width_px'].' × '.$m['height_px'].' px</td></tr>';
 echo '</tbody></table></div><button class="btn btn-primary mt-3">Generar listas con los seleccionados</button></form><script defer src="'.h(url('assets/js/playlist-generator.js')).'?v=0429"></script>';
